package report

// BUG: += on a string COPIES the whole accumulator on every iteration -
// O(n^2) in total characters and far too slow for large reports.
func JoinLines(lines []string) string {
	out := ""
	for _, line := range lines {
		out += line + "\n"
	}
	return out
}

test_setup_files.report_test.go:
package report

import (
	"strings"
	"testing"
	"time"
)

func TestJoinLinesBasic(t *testing.T) {
	got := JoinLines([]string{"a", "b", "c"})
	want := "a\nb\nc\n"
	if got != want {
		t.Fatalf("JoinLines(...) = %q, want %q (every line newline-terminated)", got, want)
	}
}

func TestJoinLinesEmpty(t *testing.T) {
	if got := JoinLines(nil); got != "" {
		t.Fatalf("empty input must give an empty string, got %q", got)
	}
}

func TestJoinLinesPerformance(t *testing.T) {
	n := 40000
	lines := make([]string, n)
	for i := range lines {
		lines[i] = "line of representative report text here"
	}

	start := time.Now()
	got := JoinLines(lines)
	elapsed := time.Since(start)

	if !strings.HasPrefix(got, lines[0]+"\n") || !strings.HasSuffix(got, lines[n-1]+"\n") {
		t.Fatalf("large-input content wrong")
	}
	// calibrated: += in the loop is ~2.5s on fast native hardware at
	// n=40000 and slower in the sandbox; strings.Builder is ~0.001s
	if elapsed >= 1200*time.Millisecond {
		t.Fatalf("JoinLines took %v for %d lines; expected a strings.Builder, "+
			"not += which copies the whole accumulator every iteration", elapsed, n)
	}
}

reference_solution.report.go:
package report

import "strings"

func JoinLines(lines []string) string {
	var b strings.Builder
	for _, line := range lines {
		b.WriteString(line)
		b.WriteByte('\n')
	}
	return b.String()
}

